function searchWords(text:string){return text.toLowerCase().normalize('NFKD').replace(/\p{M}/gu,'').replace(/(\d),(?=\d)/g,'$1').replace(/[^\p{L}\p{N}]+/gu,' ').trim().split(/\s+/).filter(Boolean);}
function matchesTakeSearch(thesis:Thesis,terms:string[]){
  if(!terms.length)return true;
  const creator=creatorFor(thesis);
  const words=searchWords([thesis.title,thesis.body,thesis.summary,thesis.category,creator.name,creator.handle||'',...thesis.allocations.flatMap(a=>{const token=tokenFor(thesis,a.symbol);return [a.symbol,token.symbol,token.name];})].join(' '));
  return terms.every(term=>words.some(word=>word.startsWith(term)));
}
