async function saveDraft(){if(!draft)return;if(draft.allocations.length<1||draft.allocations.length>MAX_THESIS_TOKENS){setFormError(`Choose 1–${MAX_THESIS_TOKENS} tokens, including USDC.`);return;}const existing=state.theses.find(t=>t.id===draft.id&&!t.example);const visibility=existing?.visibility==='private'?'private':'public';if(visibility==='public'&&!state.user?.creator){setEditingCreator(true);return;}setWorking(true);setFormError('');try{if(draft.exitPlan)validateExitPlan(draft.exitPlan,draft);const d=await post({action:'save',thesis:draft,visibility});await refresh();navigate(d.thesis.id);setModal(null);toast.success(existing?'Your changes are saved.':'Your take is live in the feed.');}catch(e){setFormError((e as Error).message);}finally{setWorking(false);}}
const receiveIdentity=useCallback((identity:TakeIdentity,originalTitle:string)=>{setDraft(d=>d?.id===identity.thesisId?{...d,title:manuallyNamed.current!==d.id&&d.title===originalTitle&&d.body===identity.body?identity.title:d.title,artworkId:['ready','generating'].includes(identity.status)?identity.id:undefined,artworkStatus:identity.status}:d);},[]);
async function publishCurrent(){if(!current)return;if(!state.user?.creator){setEditingCreator(true);return;}setWorking(true);try{await post({action:'publish',thesisId:current.id});await refresh();toast.success('Your take is live in the feed.');}catch(e){toast.error((e as Error).message);}finally{setWorking(false);}}
function startTrade(side:string,amount?:string,target=current){
  if(!target)return;
  if(side==='buy'&&!isTakeLive(target)){toast.error('This take is closed to new investment.');return;}
  const targetPosition=state.positions.find(p=>p.thesisId===target.id);
  setExecutionMode(side==='sell'&&targetPosition?targetPosition.executionMode||'spot':hasPerps(target)?'perps':'spot');
  setLeverage(side==='sell'&&targetPosition?targetPosition.leverage||1:Math.max(1,...target.allocations.filter(a=>a.execution==='perps').map(a=>a.leverage||1)));
  setRiskAccepted(false);
  if(side==='buy'&&target.id===current?.id&&hasPerps(target))perps.retry();
  setTradeSide(side);
  setTradeAmount(side==='sell'?String((targetPosition?.amount||0)/100):(amount??(defaultBuyAmount/100).toFixed(2)));
  openModal('trade');
}
function buyTake(target:Thesis){navigate(target.id);startTrade('buy',undefined,target);}

